function render(){const legacy={oci:'contracts/supplier/oci',policies:'contracts/customer/'+state.selected,preview:'contracts/customer/'+state.selected+'/preview'};const old=location.hash.slice(1);if(legacy[old]){location.replace('#'+legacy[old]);return;}shell();const route=location.hash.slice(1)||'operations';if(route==='operations')operations();else if(route.startsWith('detail/'))detail(route.split('/')[1]);else if(route==='contracts'||route.startsWith('contracts/'))contractRoute(route);else if(route==='history')history();else content.innerHTML=title('404',t('View not found','화면 없음'),'');}
window.addEventListener('hashchange',()=>{render();if(location.hash==='#operations'){const a=document.querySelector(`a[href="#detail/${state.selected}"]`);if(a)a.focus();else content.focus();}else content.focus();});
